theorem Std.Internal.List.forIn_eq_forIn_toProd.{u, v, w, w'} {α : Type u} {β : Type v} {δ : Type w}
  {m' : Type w → Type w'} [Monad m'] [LawfulMonad m'] {l : List ((_ : α) × β)}
  {f : α → β → δ → m' (ForInStep δ)} {init : δ} :
  (forIn l init fun a d => f a.fst a.snd d) =
    forIn (List.map (fun x => (x.fst, x.snd)) l) init fun a d => f a.1 a.2 d

theorem Std.DTreeMap.Internal.Cell.mk.congr_simp.{u, v} {α : Type u} [Ord α] {β : α → Type v}
  {k : α → Ordering} (inner inner✝ : Option ((a : α) × β a)) (e_inner : inner = inner✝)
  (property : ∀ [Std.OrientedOrd α] (p : (a : α) × β a), inner = some p → k p.fst = Ordering.eq) :
  { inner := inner, property := property } = { inner := inner✝, property := ⋯ }

theorem Std.DTreeMap.Internal.Cell.mk.inj.{u, v} {α : Type u} {inst✝ : Ord α} {β : α → Type v}
  {k : α → Ordering} {inner : Option ((a : α) × β a)}
  {property : ∀ [Std.OrientedOrd α] (p : (a : α) × β a), inner = some p → k p.fst = Ordering.eq}
  {inner✝ : Option ((a : α) × β a)}
  {property✝ : ∀ [Std.OrientedOrd α] (p : (a : α) × β a), inner✝ = some p → k p.fst = Ordering.eq} :
  { inner := inner, property := property } = { inner := inner✝, property := property✝ } →
    inner = inner✝

def Std.DTreeMap.Internal.Cell.ofEq.{u, v} {α : Type u} {β : α → Type v} [Ord α] {k : α → Ordering}
  (k' : α) (v' : β k') (hcmp : ∀ [Std.OrientedOrd α], k k' = Ordering.eq) :
  Std.DTreeMap.Internal.Cell α β k

theorem Std.DTreeMap.Internal.Cell.property.{u, v} {α : Type u} [Ord α] {β : α → Type v} {k : α → Ordering}
  (self : Std.DTreeMap.Internal.Cell α β k) [Std.OrientedOrd α] (p : (a : α) × β a) :
  self.inner = some p → k p.fst = Ordering.eq
